import { useState } from 'react';
import { FileSpreadsheet, Download, AlertCircle, Loader2, CheckCircle2 } from 'lucide-react';
import api from '../lib/axios';

export const Reports = () => {
  const [isDownloading, setIsDownloading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleDownload = async () => {
    setIsDownloading(true);
    setError('');
    setSuccess(false);

    try {
      // 1. Fetch the file as a Blob (Binary Data)
      const response = await api.get('/reports/download', {
        responseType: 'blob', // Critical for file downloads!
      });

      // 2. Create a temporary URL for the Blob
      const url = window.URL.createObjectURL(new Blob([response.data]));
      
      // 3. Create a hidden link element and click it to trigger the download
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', 'FarmLink_Marketplace_Report.xlsx'); // File name
      document.body.appendChild(link);
      link.click();

      // 4. Clean up the DOM and URL object
      link.parentNode.removeChild(link);
      window.URL.revokeObjectURL(url);
      
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000); // Hide success message after 3s

    } catch (err) {
      // Axios wraps blob errors differently, so we have to parse it back to text if it's a JSON error message
      if (err.response && err.response.data instanceof Blob) {
        const errorText = await err.response.data.text();
        try {
          const parsedError = JSON.parse(errorText);
          setError(parsedError.message || 'Failed to download report.');
        } catch (e) {
          setError('An unexpected error occurred.');
        }
      } else {
        setError(err.response?.status === 403 ? 'Access Denied: Admin privileges required.' : 'Failed to connect to server.');
      }
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      
      <div>
        <h2 className="text-2xl font-bold text-gray-900">System Reports</h2>
        <p className="text-sm text-gray-500">Export marketplace analytics and order history.</p>
      </div>

      {error && (
        <div className="p-4 bg-red-50 text-red-700 rounded-xl flex items-center gap-3 border border-red-200">
          <AlertCircle size={20} />
          <span className="font-medium">{error}</span>
        </div>
      )}

      {success && (
        <div className="p-4 bg-green-50 text-green-700 rounded-xl flex items-center gap-3 border border-green-200">
          <CheckCircle2 size={20} />
          <span className="font-medium">Report downloaded successfully!</span>
        </div>
      )}

      <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-8 text-center max-w-2xl mx-auto mt-12">
        <div className="w-20 h-20 bg-farmGreen/10 rounded-full flex items-center justify-center mx-auto mb-6 text-farmGreen">
          <FileSpreadsheet size={40} />
        </div>
        
        <h3 className="text-xl font-bold text-gray-900 mb-2">Complete Marketplace Export</h3>
        <p className="text-gray-500 mb-8 max-w-md mx-auto leading-relaxed">
          Download a comprehensive Excel (.xlsx) workbook containing two sheets: current produce inventory and a full log of all buyer orders.
        </p>

        <button
          onClick={handleDownload}
          disabled={isDownloading}
          className="inline-flex items-center justify-center px-8 py-3.5 bg-farmGreen hover:bg-farmGreen-dark text-white font-bold rounded-xl transition-all disabled:opacity-70 shadow-sm hover:shadow-md"
        >
          {isDownloading ? (
            <><Loader2 className="animate-spin mr-2" size={20} /> Generating Report...</>
          ) : (
            <><Download className="mr-2" size={20} /> Download Excel Report</>
          )}
        </button>
      </div>

    </div>
  );
};
